dataConfig.script:
function FilterByFilterGroupId(row){

	var filters = row.get('filter_ids').split(','); 
	var arr = new java.util.ArrayList();
	for(var i=0; i<filters.length;i++){
		arr.add(filters[i]);
	}
	row.put('filter_group_df_' + row.get('filter_group_id'), arr);
	row.remove('filter_group_id');
	row.remove('filter_ids');
	return row;
}

function Searchable(row) {
	var nickname = row.get('nickname').split('_');
	row.put('nickname_delimited', nickname.join(''));
	return row;
}
